import type { Pipeline, PipelineStage } from '../../../schema/pipeline'
import { requireKey, str } from '../octopus'

/**
 * https://developer.maximizer.com/reference/octopus-api-docs-objects-salesprocesssetup
 * "The SalesProcessSetup object is composed only by a key (autogenerated) and
 * a description for the Sales Process."
 */
export interface RawMaximizerSalesProcess {
  Key: string
  Description?: string | null
  [key: string]: unknown
}

/**
 * https://developer.maximizer.com/reference/octopus-api-docs-objects-salesstagesetup
 * "Description: The name of the stage." "ProbabilityClose: The likelihood of a
 * successful outcome at this stage." The Read example scopes Key, Description,
 * SalesProcessSetupKey, TargetAge and ProbabilityClose.
 */
export interface RawMaximizerSalesStage {
  Key: string
  Description?: string | null
  SalesProcessSetupKey?: string | null
  ProbabilityClose?: number | null
  [key: string]: unknown
}

function transformStage(raw: RawMaximizerSalesStage): PipelineStage {
  const id = requireKey(raw, 'SalesStageSetup')
  const name = str(raw.Description)
  if (!name) throw new Error(`Maximizer sales stage ${id} has no Description`)
  const p = raw.ProbabilityClose
  return {
    id,
    name,
    win_probability: typeof p === 'number' && p >= 0 && p <= 100 ? p : undefined,
  }
}

export function transformPipeline(
  raw: RawMaximizerSalesProcess,
  stages: readonly RawMaximizerSalesStage[],
): Pipeline {
  const id = requireKey(raw, 'SalesProcessSetup')
  const name = str(raw.Description)
  if (!name) throw new Error(`Maximizer sales process ${id} has no Description`)
  return {
    id,
    name,
    stages: stages.filter((s) => s.SalesProcessSetupKey === id).map(transformStage),
    metadata: raw,
  }
}
